<script setup lang="ts">import{computed,onMounted,ref}from'vue';import{useRoute}from'vue-router';import{Line}from'vue-chartjs';import{Chart as ChartJS,LineElement,PointElement,LinearScale,CategoryScale,Tooltip,Legend}from'chart.js';import{api,errorMessage}from'../lib/api';ChartJS.register(LineElement,PointElement,LinearScale,CategoryScale,Tooltip,Legend);const route=useRoute(),product=ref<any>(),series=ref<any[]>([]),movements=ref<any[]>([]),error=ref('');const chart=computed(()=>({labels:series.value.map(x=>x.date),datasets:[{label:'Inbound',data:series.value.map(x=>x.incoming),borderColor:'#39c89b'},{label:'Outbound',data:series.value.map(x=>x.outgoing),borderColor:'#ef6a6a'}]}));onMounted(async()=>{try{const[p,m]=await Promise.all([api.get(`/products/${route.params.id}`),api.get(`/inventory/${route.params.id}/movements`)]);product.value=p.data.data;series.value=m.data.data.series;movements.value=m.data.data.movements}catch(e){error.value=errorMessage(e)}})</script>
<template><div v-if="error" class="form-error">{{error}}</div><template v-if="product"><div class="page-heading"><div><p class="eyebrow">PRODUCT DETAILS</p><h1>{{product.name}}</h1><p>{{product.sku}} · {{product.category}} · {{product.brand||'Unbranded'}}</p></div><RouterLink class="secondary" to="/inventory">Back</RouterLink></div><div class="kpi-grid"><article class="kpi-card"><p>Total on hand</p><h2>{{product.inventory.reduce((s:number,x:any)=>s+x.quantityOnHand,0)}}</h2></article><article class="kpi-card"><p>Reserved</p><h2>{{product.inventory.reduce((s:number,x:any)=>s+x.quantityReserved,0)}}</h2></article><article class="kpi-card"><p>Cost price</p><h2>{{Number(product.costPrice).toLocaleString()}} EGP</h2></article><article class="kpi-card"><p>Sale price</p><h2>{{Number(product.defaultSalePrice).toLocaleString()}} EGP</h2></article></div><div class="dashboard-grid"><article class="panel chart-panel"><h3>30-day movement</h3><Line v-if="series.length" :data="chart" :options="{responsive:true,maintainAspectRatio:false}"/><div v-else class="empty">No movements in this period.</div></article><article class="panel"><h3>Stock by location</h3><ul class="activity-list"><li v-for="x in product.inventory" :key="x.id"><span class="activity-mark"/><div><strong>{{x.location.name}}</strong><small>{{x.quantityOnHand}} on hand · {{x.quantityReserved}} reserved</small></div></li></ul></article></div><article class="panel table-panel"><div class="table-wrap"><table><thead><tr><th>Date</th><th>Type</th><th>Quantity</th><th>Balance</th><th>Reference</th></tr></thead><tbody><tr v-for="m in movements.slice().reverse()" :key="m.id"><td>{{new Date(m.createdAt).toLocaleString()}}</td><td>{{m.type.replaceAll('_',' ')}}</td><td>{{m.quantity>0?'+':''}}{{m.quantity}}</td><td>{{m.balanceAfter}}</td><td>{{m.referenceType||'—'}}</td></tr></tbody></table></div></article></template></template>
